import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.BTaI8jHZ.js";const g=JSON.parse('{"title":"Failure and Recovery","description":"What happens when things break — failure modes, retry behavior, and recovery","frontmatter":{"title":"Failure and Recovery","description":"What happens when things break — failure modes, retry behavior, and recovery","audience":["operator","contributor","architect"]},"headers":[],"relativePath":"architecture/failure-and-recovery.md","filePath":"architecture/failure-and-recovery.md","lastUpdated":1775245357000}'),s={name:"architecture/failure-and-recovery.md"};function n(i,e,d,l,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="failure-and-recovery" tabindex="-1">Failure and Recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and Recovery&quot;">​</a></h1><p>What happens when external services go down, the homeserver is unreachable, or hookshot crashes. Understanding failure behavior helps operators set up <a href="./../guides/operator/monitoring">monitoring</a> and plan recovery.</p><h2 id="failure-scenarios" tabindex="-1">Failure scenarios <a class="header-anchor" href="#failure-scenarios" aria-label="Permalink to &quot;Failure scenarios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>System behavior</th><th>Recovery</th><th>Detection</th></tr></thead><tbody><tr><td><strong>External service down</strong></td><td>Outbound <a href="./../reference/bot-commands">commands</a> fail with error message in room. Inbound webhooks stop arriving (external side).</td><td>Automatic when service recovers. No hookshot restart needed.</td><td><code>hookshot_connection_event_failed</code> metric, error messages in rooms</td></tr><tr><td><strong>Homeserver unreachable</strong></td><td>On startup: retries every 5s until connected. At runtime: message sends fail, queued for retry.</td><td>Automatic reconnection. Messages may be lost if queue is in-memory (<a href="./state-and-storage#localmq-default">LocalMQ</a>).</td><td><code>matrix_api_calls_failed</code> metric, startup logs</td></tr><tr><td><strong>Webhook signature mismatch</strong></td><td>HTTP 401 returned, event silently dropped.</td><td>Fix secret in <a href="./../guides/operator/configuration">config</a> or external service settings.</td><td>Logs at warn level, <code>hookshot_webhooks_http_request</code> without corresponding <code>hookshot_queue_event_pushes</code></td></tr><tr><td><strong>Connection not found</strong></td><td>Event arrives but no matching <a href="./connections">connection</a>. Silently dropped.</td><td>Create connection in the room, or check <a href="./../reference/event-types">event types</a> match.</td><td>Debug-level logs only</td></tr><tr><td><strong>Event type disabled</strong></td><td>Connection exists but this event type isn&#39;t in <code>enableHooks</code>. Silently dropped.</td><td>Update connection config to enable the event type.</td><td>Not logged — by design</td></tr><tr><td><strong>Transformation function error</strong></td><td><a href="./../integrations/generic-webhooks">Generic webhook</a> transformation throws or times out. No message sent.</td><td>Fix transformation function. Test with simpler input.</td><td><code>hookshot_connection_event_failed</code> metric, warn-level logs</td></tr><tr><td><strong>Matrix message too large</strong></td><td>Message exceeds ~65KB event limit. Trimmed automatically.</td><td>Reduce payload size or transformation output.</td><td>Warn-level log</td></tr><tr><td><strong>Redis down</strong></td><td><a href="./state-and-storage#redismq-worker-mode">RedisMQ</a>: all event routing stops. <a href="./state-and-storage#redisstorageprovider">RedisStorage</a>: dedup stops, feeds may re-post.</td><td>Restart Redis. Hookshot auto-reconnects.</td><td>Queue metrics flat, connection errors in logs</td></tr><tr><td><strong>Hookshot crash/restart</strong></td><td>All <a href="./connections">connections</a> reconstructed from <a href="./state-and-storage#matrix-room-state-as-primary-store">room state</a>. In-flight events lost. Feed state lost without Redis.</td><td>Automatic on restart. <a href="./../integrations/feeds">Feed</a> entries may re-post without Redis.</td><td>Process monitoring, <code>/ready</code> <a href="./../guides/operator/monitoring#health-probes">health probe</a></td></tr><tr><td><strong>Token store corrupted</strong></td><td><a href="./../understand/trust-and-boundaries#token-store">OAuth tokens</a> unreadable. Users appear unauthenticated.</td><td>Users re-authenticate. If <code>passFile</code> is lost, all tokens must be recreated.</td><td><a href="./../troubleshooting/authentication#check-5-is-the-token-store-working">Authentication errors</a></td></tr><tr><td><strong>Encryption state corrupted</strong></td><td><a href="./../guides/operator/encryption">E2EE</a> messages fail.</td><td>Reset crypto store: <code>yarn start:resetcrypto</code>.</td><td>Decryption failure metrics, <a href="./../troubleshooting/common-errors#startup-errors">encryption troubleshooting</a></td></tr></tbody></table><h2 id="startup-resilience" tabindex="-1">Startup resilience <a class="header-anchor" href="#startup-resilience" aria-label="Permalink to &quot;Startup resilience&quot;">​</a></h2><p>Hookshot&#39;s startup sequence handles failures at each stage:</p><ol><li><strong>Homeserver connection</strong> — retries every 5 seconds indefinitely until reachable</li><li><strong>Room state loading</strong> — processes rooms with concurrency of 2; one failing room doesn&#39;t block others</li><li><strong>Connection reconstruction</strong> — invalid state events are logged and skipped, not fatal</li><li><strong>Service initialization</strong> — GitHub/Figma webhook setup failures are logged but don&#39;t prevent startup</li></ol><h2 id="message-delivery-guarantees" tabindex="-1">Message delivery guarantees <a class="header-anchor" href="#message-delivery-guarantees" aria-label="Permalink to &quot;Message delivery guarantees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Guarantee</th><th>Risk</th></tr></thead><tbody><tr><td>Inbound webhook → Matrix message</td><td>At-most-once (LocalMQ)</td><td>Event lost if hookshot crashes mid-processing</td></tr><tr><td>Inbound webhook → Matrix message</td><td>At-most-once (RedisMQ)</td><td>Event lost if consumer crashes after dequeue</td></tr><tr><td>Outbound command → external API</td><td>At-most-once</td><td>Command fails if external API is unreachable</td></tr><tr><td>Feed polling → Matrix message</td><td>At-least-once with Redis</td><td>Entry may re-post if Redis state is lost</td></tr><tr><td>Feed polling → Matrix message</td><td>At-least-once without Redis</td><td>Re-posts all entries after restart</td></tr></tbody></table><p>Hookshot does <strong>not</strong> provide exactly-once delivery. Duplicate messages are possible in edge cases (feed re-polling, webhook retries from external services).</p><h2 id="feed-polling-resilience" tabindex="-1">Feed polling resilience <a class="header-anchor" href="#feed-polling-resilience" aria-label="Permalink to &quot;Feed polling resilience&quot;">​</a></h2><p><a href="./../integrations/feeds">Feed connections</a> have built-in error handling:</p><ul><li><strong>Retry on send failure:</strong> 5 attempts with 5-second intervals</li><li><strong>Error tracking:</strong> Last 5 poll results stored (timestamp, success/error)</li><li><strong>Optional error notification:</strong> <code>notifyOnFailure: true</code> sends a message when polling fails</li><li><strong>Backoff:</strong> Under load, polling interval may increase (never decreases below configured interval)</li><li><strong>Deduplication:</strong> MD5 hash of entry GUID prevents re-posting seen entries (requires <a href="./state-and-storage#redisstorageprovider">Redis</a> for persistence)</li></ul><h2 id="what-to-monitor" tabindex="-1">What to monitor <a class="header-anchor" href="#what-to-monitor" aria-label="Permalink to &quot;What to monitor&quot;">​</a></h2><p>Set up <a href="./../guides/operator/monitoring#alert-suggestions">Prometheus alerts</a> for:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Alert condition</th><th>Meaning</th></tr></thead><tbody><tr><td><code>matrix_api_calls_failed</code></td><td>Increasing</td><td>Homeserver communication failing</td></tr><tr><td><code>hookshot_connection_event_failed</code></td><td>Increasing</td><td>Events failing to process</td></tr><tr><td><code>hookshot_queue_event_pushes</code></td><td>Flat for &gt;1h</td><td>No webhook traffic (may be expected)</td></tr><tr><td><code>hookshot_feeds_failing</code></td><td>&gt; 0</td><td>Feeds failing to fetch</td></tr><tr><td>Process health</td><td><code>/ready</code> returns non-200</td><td>Hookshot not fully initialized</td></tr></tbody></table><h2 id="recovery-procedures" tabindex="-1">Recovery procedures <a class="header-anchor" href="#recovery-procedures" aria-label="Permalink to &quot;Recovery procedures&quot;">​</a></h2><h3 id="after-hookshot-restart" tabindex="-1">After hookshot restart <a class="header-anchor" href="#after-hookshot-restart" aria-label="Permalink to &quot;After hookshot restart&quot;">​</a></h3><p>No action needed. Connections are automatically reconstructed from <a href="./state-and-storage#startup-reconstruction">room state</a>. Check logs for <code>Bridge has started</code>.</p><h3 id="after-redis-outage" tabindex="-1">After Redis outage <a class="header-anchor" href="#after-redis-outage" aria-label="Permalink to &quot;After Redis outage&quot;">​</a></h3><p>Redis auto-reconnects. Feed state may be stale — some entries may re-post. No manual action needed.</p><h3 id="after-homeserver-database-reset" tabindex="-1">After homeserver database reset <a class="header-anchor" href="#after-homeserver-database-reset" aria-label="Permalink to &quot;After homeserver database reset&quot;">​</a></h3><p>If the homeserver&#39;s database is wiped:</p><ol><li>All room state (connections) is lost</li><li>Hookshot&#39;s <a href="./../guides/operator/encryption#crypto-store">crypto store</a> must be reset: <code>yarn start:resetcrypto</code></li><li>Users must re-create connections and re-authenticate</li></ol><h3 id="after-passkey-loss" tabindex="-1">After passkey loss <a class="header-anchor" href="#after-passkey-loss" aria-label="Permalink to &quot;After passkey loss&quot;">​</a></h3><p>If <code>passFile</code> is lost or changed:</p><ol><li>All stored OAuth tokens become unreadable</li><li>Users must re-authenticate with each service</li><li>Generate a new passkey and <a href="./../guides/operator/hardening#credential-protection">back it up</a></li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./../understand/event-lifecycle">Event Lifecycle</a> · <a href="./../understand/trust-and-boundaries">Trust and Boundaries</a></p><p><strong>Architecture:</strong> <a href="./connections">Connections</a> · <a href="./state-and-storage">State and Storage</a> · <a href="./component-model">Component Model</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/monitoring">Monitoring</a> · <a href="./../guides/operator/upgrading">Upgrading</a> · <a href="./../guides/operator/encryption">Encryption</a> · <a href="./../guides/operator/hardening">Hardening</a></p><p><strong>Troubleshooting:</strong> <a href="./../troubleshooting/common-errors">Common Errors</a> · <a href="./../troubleshooting/webhooks-not-arriving">Webhooks Not Arriving</a> · <a href="./../troubleshooting/authentication">Authentication</a></p>',32)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
